-- generated from signals_kw.json; save column j as source/projects.json
with p0 as (select *, coalesce(name,'')||' '||coalesce(abstract,'') t from projects where coalesce(funding_stream,'')||' '||coalesce(programme,'') ~* '(NIA|NIC|SIF|IFI|Network Innovation)')
select json_build_object('total',(select count(*) from projects),'total_innovation',(select count(*) from p0),
 'by_owner',(select json_object_agg(o,c) from (select coalesce(owner_network_id,'none') o,count(*) c from p0 group by 1) z),
 'storm',(select json_build_object('n',count(*),'sub_n',count(*) filter (where t ~* '(storm|post-storm|fault find|fault-find|restoration|restore)'),
 'by_owner',(select json_object_agg(o,c) from (select coalesce(owner_network_id,'none') o,count(*) c from p0 where t ~* '(drone|robot|\muav\M|bvlos|unmanned aerial)' group by 1) z),
 'items',(select json_agg(i) from (select external_ref,name,status,funding_stream,owner_network_id,start_date,url, t ~* '(storm|post-storm|fault find|fault-find|restoration|restore)' sub from p0 where t ~* '(drone|robot|\muav\M|bvlos|unmanned aerial)' order by (t ~* '(storm|post-storm|fault find|fault-find|restoration|restore)') desc, start_date desc nulls last limit 12) i))
